html:
{%- set settings = frappe.get_doc("LandMS Settings", "LandMS Settings") -%}
{%- set company_doc = frappe.get_doc("Company", settings.company) -%}
{%- set customer_doc = frappe.get_doc("Customer", doc.customer) -%}
{%- set plot_invoice = frappe.get_doc("Sales Invoice", doc.plot_sales_invoice) if doc.plot_sales_invoice and frappe.db.exists("Sales Invoice", doc.plot_sales_invoice) else None -%}
{%- set selling_price = doc.grand_total or 0 -%}
{%- set advance_amount = (selling_price * (doc.booking_fee_percent or 0) / 100) -%}
{%- set balance_due = selling_price - advance_amount -%}
{%- set total_contract_value = plot_invoice.grand_total if plot_invoice else selling_price -%}
{%- set total_outstanding = plot_invoice.outstanding_amount if plot_invoice else (doc.plot_outstanding_amount or selling_price) -%}
{%- set total_paid = (plot_invoice.grand_total - plot_invoice.outstanding_amount) if plot_invoice else (doc.advance_paid or 0) -%}
{%- set schedule_rows = plot_invoice.payment_schedule if plot_invoice and plot_invoice.payment_schedule else doc.payment_schedule -%}
<div class="pso-wrap">
  <div class="stmt-header">
    <h1>{{ company_doc.company_name | upper }}</h1>
    {% if company_doc.company_tagline %}<h2>{{ company_doc.company_tagline }}</h2>{% endif %}
    {% if company_doc.phone_no %}<h2>Tel: {{ company_doc.phone_no }}{% if company_doc.email %} | {{ company_doc.email }}{% endif %}</h2>{% endif %}
  </div>
  <div class="stmt-title"><span>LAND SALES ORDER</span></div>
  <div class="tcb-box">
    <div class="tcb-label">TCB Control Number - Use this number for all payments</div>
    <div class="tcb-number">{{ doc.control_number or 'Not yet generated' }}</div>
  </div>
  <div class="meta-grid">
    <div class="meta-block">
      <h4>Customer</h4>
      <p><strong>{{ doc.customer }}</strong></p>
      {% if customer_doc.mobile_no %}<p class="label">Mobile: {{ customer_doc.mobile_no }}</p>{% endif %}
      {% if customer_doc.customer_primary_address %}
      {%- set addr = frappe.get_doc("Address", customer_doc.customer_primary_address) -%}
      {% if addr.address_line1 %}<p>{{ addr.address_line1 }}</p>{% endif %}
      {% if addr.city %}<p>{{ addr.city }}</p>{% endif %}
      {% endif %}
    </div>
    <div class="meta-block">
      <h4>Order Details</h4>
      <p><span class="label">Order No:</span> <strong>{{ doc.name }}</strong></p>
      <p><span class="label">Plot:</span> {{ doc.plot }}</p>
      <p><span class="label">Order Date:</span> {{ doc.transaction_date }}</p>
      <p><span class="label">Advance Deadline:</span> <strong>{{ doc.payment_deadline }}</strong></p>
      <p><span class="label">Payment Window:</span> {{ doc.payment_completion_days }} days</p>
      {% if doc.plot_contract %}<p><span class="label">Plot Contract:</span> <strong>{{ doc.plot_contract }}</strong></p>{% endif %}
      {% if doc.plot_sales_invoice %}<p><span class="label">Plot Sales Invoice:</span> <strong>{{ doc.plot_sales_invoice }}</strong></p>{% endif %}
    </div>
  </div>
  <div class="hc-section-title">Financials</div>
  <table class="schedule">
    <tbody>
      <tr>
        <td class="hc-lbl">Selling Price (TZS)</td>
        <td style="text-align:right"><strong>{{ "{:,.0f}".format(selling_price or 0) }}</strong></td>
        <td class="hc-lbl">Advance ({{ doc.booking_fee_percent or 0 }}%)</td>
        <td style="text-align:right"><strong>{{ "{:,.0f}".format(advance_amount or 0) }}</strong></td>
      </tr>
      <tr>
        <td class="hc-lbl">Remaining Balance (TZS)</td>
        <td style="text-align:right"><strong>{{ "{:,.0f}".format(balance_due or 0) }}</strong></td>
        <td class="hc-lbl">Total Paid (TZS)</td>
        <td style="text-align:right"><strong>{{ "{:,.0f}".format(total_paid or 0) }}</strong></td>
      </tr>
    </tbody>
  </table>
  <div class="hc-section-title">Installment Schedule</div>
  <table class="schedule">
    <thead>
      <tr>
        <th style="width:5%">#</th>
        <th style="width:25%">Description</th>
        <th style="width:15%">Due Date</th>
        <th style="width:18%; text-align:right">Expected (TZS)</th>
        <th style="width:18%; text-align:right">Paid (TZS)</th>
        <th style="width:10%; text-align:center">Status</th>
      </tr>
    </thead>
    <tbody>
      {% for row in schedule_rows %}
      {%- set expected = row.payment_amount or 0 -%}
      {%- set paid = row.paid_amount or 0 -%}
      {%- set status = 'Pending' -%}
      {%- if expected > 0 and paid >= expected -%}
        {%- set status = 'Paid' -%}
      {%- elif row.due_date and frappe.utils.getdate(row.due_date) < frappe.utils.getdate(frappe.utils.today()) -%}
        {%- set status = 'Overdue' -%}
      {%- endif -%}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ row.description or ('Installment ' ~ loop.index) }}</td>
        <td>{{ row.due_date }}</td>
        <td style="text-align:right">{{ "{:,.0f}".format(expected) }}</td>
        <td style="text-align:right">{{ "{:,.0f}".format(paid) }}</td>
        <td style="text-align:center">{{ status }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  <div class="summary-wrap">
    <table class="summary-table">
      <tr class="total-row"><td>Total Contract Value</td><td style="text-align:right">TZS {{ "{:,.0f}".format(total_contract_value or 0) }}</td></tr>
      <tr><td>Total Paid</td><td style="text-align:right; color:#155724">TZS {{ "{:,.0f}".format(total_paid or 0) }}</td></tr>
      <tr class="outstanding-row"><td>Outstanding Balance</td><td style="text-align:right">TZS {{ "{:,.0f}".format(total_outstanding or 0) }}</td></tr>
    </table>
  </div>
  {% if doc.terms %}
  <div class="hc-section-title">Terms</div>
  <div style="border:1px solid #ddd; background:#fffef0; padding:10px 14px; white-space:pre-wrap; line-height:1.6;">{{ doc.terms }}</div>
  {% endif %}
  <div class="footer">
    <p>All plot payments must be made using TCB Control Number: <strong>{{ doc.control_number or 'N/A' }}</strong></p>
    <p>{{ doc.name }} | {{ company_doc.company_name }} | Printed: {{ frappe.utils.today() }} | This is a computer-generated document.</p>
  </div>
</div>

css:
body { font-family: Arial, sans-serif; font-size: 13px; color: #1a1a1a; }
.pso-wrap { max-width: 820px; margin: 0 auto; }
.stmt-header { text-align: center; border-bottom: 3px solid #2c5f2e; padding-bottom: 12px; margin-bottom: 20px; }
.stmt-header h1 { margin: 0; font-size: 22px; color: #2c5f2e; letter-spacing: 2px; }
.stmt-header h2 { margin: 4px 0 0; font-size: 13px; font-weight: normal; color: #555; }
.stmt-title { text-align: center; margin: 0 0 20px; }
.stmt-title span { font-size: 16px; font-weight: bold; letter-spacing: 3px; border: 2px solid #2c5f2e; padding: 4px 18px; color: #2c5f2e; }
.tcb-box { border: 3px solid #2c5f2e; padding: 14px; text-align: center; margin: 0 0 22px; background: #f0f7f0; }
.tcb-box .tcb-label { font-size: 11px; text-transform: uppercase; color: #2c5f2e; font-weight: bold; letter-spacing: 0.8px; }
.tcb-box .tcb-number { font-size: 24px; font-weight: bold; letter-spacing: 3px; margin-top: 4px; color: #1a1a1a; }
.meta-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 40px; margin-bottom: 20px; }
.meta-block h4 { margin: 0 0 6px; font-size: 11px; text-transform: uppercase; color: #888; border-bottom: 1px solid #ddd; padding-bottom: 3px; }
.meta-block p { margin: 3px 0; font-size: 13px; }
.meta-block .label { color: #666; font-size: 11px; }
.hc-section-title { font-weight: bold; font-size: 11px; text-transform: uppercase; letter-spacing: 0.8px; border-bottom: 2px solid #2c5f2e; padding-bottom: 4px; margin: 22px 0 10px; color: #2c5f2e; }
.hc-lbl { background: #f0f7f0; font-weight: bold; font-size: 11px; width: 20%; white-space: nowrap; color: #2c5f2e; }
table.schedule { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
table.schedule thead th { background: #2c5f2e; color: #fff; padding: 8px 10px; text-align: left; font-size: 12px; }
table.schedule tbody td { padding: 8px 10px; border-bottom: 1px solid #eee; font-size: 13px; }
.summary-wrap { display: flex; justify-content: flex-end; margin-bottom: 20px; }
.summary-table { width: 340px; border-collapse: collapse; }
.summary-table td { padding: 6px 10px; font-size: 13px; border-bottom: 1px solid #eee; }
.summary-table .total-row { font-weight: bold; font-size: 14px; background: #f0f7f0; border-top: 2px solid #2c5f2e; }
.summary-table .outstanding-row { font-weight: bold; font-size: 16px; background: #fff3cd; border-top: 2px solid #c0392b; color: #c0392b; }
.footer { border-top: 1px solid #ddd; padding-top: 10px; margin-top: 20px; font-size: 11px; color: #888; text-align: center; }
